/**
 * Exo GEMVER driver: mirrors PolyBench/C gemver.c but calls the Exo-generated kernel.
 *
 * Original authors:
 *   Louis-Noel Pouchet <pouchet.ohio-state.edu>
 *   Tomofumi Yuki <tomofumi.yuki.fr>
 *
 * Web address: http://polybench.sourceforge.net
 */
/* gemver.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemver.h"

/* Include the Exo-generated kernel header. */
#include "generated/gemver/gemver.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE *alpha,
		 DATA_TYPE *beta,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(u1,N,n),
		 DATA_TYPE POLYBENCH_1D(v1,N,n),
		 DATA_TYPE POLYBENCH_1D(u2,N,n),
		 DATA_TYPE POLYBENCH_1D(v2,N,n),
		 DATA_TYPE POLYBENCH_1D(w,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  DATA_TYPE fn = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
    {
      u1[i] = i;
      u2[i] = ((i+1)/fn)/2.0;
      v1[i] = ((i+1)/fn)/4.0;
      v2[i] = ((i+1)/fn)/6.0;
      y[i] = ((i+1)/fn)/8.0;
      z[i] = ((i+1)/fn)/9.0;
      x[i] = 0.0;
      w[i] = 0.0;
      for (j = 0; j < n; j++)
        A[i][j] = (DATA_TYPE) (i*j % n) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(w,N,n))
{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("w");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, w[i]);
  }
  POLYBENCH_DUMP_END("w");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Baseline GEMVER kernel in Exo. This matches the PolyBench semantics but
# is written in a way that makes access patterns explicit and amenable
# to scheduling.
@proc
def kernel_gemver_base(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    u1: DATA_TYPE[n] @ DRAM,
    v1: DATA_TYPE[n] @ DRAM,
    u2: DATA_TYPE[n] @ DRAM,
    v2: DATA_TYPE[n] @ DRAM,
    w: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    z: DATA_TYPE[n] @ DRAM,
):
    # Rank-1 updates: A = A + u1 * v1^T + u2 * v2^T
    for i in seq(0, n):
        for j in seq(0, n):
            # Use a reduction-style update so Exo can treat this as a reduction.
            A[i, j] += u1[i] * v1[j] + u2[i] * v2[j]

    # x = x + beta * A^T * y
    # Iterate over rows of A (index j) in the outer loop so A[j, i]
    # is accessed in row-major order.
    for j in seq(0, n):
        for i in seq(0, n):
            x[i] += beta * A[j, i] * y[j]

    # x = x + z
    for i in seq(0, n):
        x[i] += z[i]

    # w = w + alpha * A * x
    for i in seq(0, n):
        for j in seq(0, n):
            w[i] += alpha * A[i, j] * x[j]


# Start from the simple specification and apply performance-oriented scheduling.
p = kernel_gemver_base

# Tunable tile sizes for cache blocking. These are compile-time constants;
# adjust them here to retune for a different cache hierarchy.
TI = 32  # tile size along the i (row) dimension
TJ = 32  # tile size along the j (column) dimension

# ---------------------------------------------------------------------------
# 1) Tile and parallelize the rank-1 update of A.
#    We block the (i, j) space so each thread works on cache-friendly tiles
#    of A and reuses u1/u2 and v1/v2 from registers.
# ---------------------------------------------------------------------------

# Get the outer (i) and inner (j) loops of the first nest.
i_A = p.find_loop("i")           # first 'i' loop: rank-1 update
j_A = i_A.body().find_loop("j")  # its inner 'j' loop

# Split i into outer/inner tile loops: i -> (io, ii).
p = divide_loop(p, i_A, TI, ("io", "ii"), tail="guard")

# Split j into outer/inner tile loops: j -> (jo, jj).
p = divide_loop(p, j_A, TJ, ("jo", "jj"), tail="guard")

# After tiling we have: for io, for ii, for jo, for jj.
# Reorder to operate on rectangular tiles: for io, for jo, for ii, for jj.
io = p.find_loop("io")
ii = io.body().find_loop("ii")
p = reorder_loops(p, ii)

# Parallelize across tiles in the i-dimension.
# Each (io, jo) tile updates a disjoint block of A, so this is safe.
p = parallelize_loop(p, io)

# ---------------------------------------------------------------------------
# 2) Parallelize the element-wise update x[i] += z[i].
# ---------------------------------------------------------------------------

# Collect all remaining 'for i in ...' loops.
i_loops = p.find_all("for i in _:_")
# At this point:
#   i_loops[0] : inner i-loop of the A^T * y GEMV
#   i_loops[1] : x[i] += z[i] loop
#   i_loops[2] : outer i-loop of the final w update
x_plus_z_i = i_loops[1]

# x[i] += z[i] is a pure element-wise operation, safe to parallelize.
p = parallelize_loop(p, x_plus_z_i)

# ---------------------------------------------------------------------------
# 3) Tile and parallelize the final matrix-vector product updating w.
#    We block A in (i, j) again so each thread works on row-tiles of A and w.
# ---------------------------------------------------------------------------

w_i = i_loops[2]                # outer i-loop of w update (from the same list)
w_j = w_i.body().find_loop("j") # its inner j-loop

# Split i -> (io2, ii2) for tiling over rows.
p = divide_loop(p, w_i, TI, ("io2", "ii2"), tail="guard")

# Split j -> (jo2, jj2) for tiling over columns.
p = divide_loop(p, w_j, TJ, ("jo2", "jj2"), tail="guard")

# Reorder inside the tile: for io2, for jo2, for ii2, for jj2.
io2 = p.find_loop("io2")
ii2 = io2.body().find_loop("ii2")
p = reorder_loops(p, ii2)

# Parallelize across tiles of rows.
p = parallelize_loop(p, io2)

# ---------------------------------------------------------------------------
# 4) Expose the optimized kernel under the name expected by the C driver.
# ---------------------------------------------------------------------------

kernel_gemver = rename(p, "kernel_gemver")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(u1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(u2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(w,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(z,  DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(u1),
	      POLYBENCH_ARRAY(v1),
	      POLYBENCH_ARRAY(u2),
	      POLYBENCH_ARRAY(v2),
	      POLYBENCH_ARRAY(w),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y),
	      POLYBENCH_ARRAY(z));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten PolyBench views to raw pointers. */
  kernel_gemver(/*ctxt=*/NULL, n,
                (DATA_TYPE*)&alpha,
                (DATA_TYPE*)&beta,
                (DATA_TYPE*)POLYBENCH_ARRAY(A),
                (DATA_TYPE*)POLYBENCH_ARRAY(u1),
                (DATA_TYPE*)POLYBENCH_ARRAY(v1),
                (DATA_TYPE*)POLYBENCH_ARRAY(u2),
                (DATA_TYPE*)POLYBENCH_ARRAY(v2),
                (DATA_TYPE*)POLYBENCH_ARRAY(w),
                (DATA_TYPE*)POLYBENCH_ARRAY(x),
                (DATA_TYPE*)POLYBENCH_ARRAY(y),
                (DATA_TYPE*)POLYBENCH_ARRAY(z));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(w)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(u1);
  POLYBENCH_FREE_ARRAY(v1);
  POLYBENCH_FREE_ARRAY(u2);
  POLYBENCH_FREE_ARRAY(v2);
  POLYBENCH_FREE_ARRAY(w);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(z);

  return 0;
}
