/*
 * Kernel implementation in Exo.
 *
 * We first describe a straightforward, reference implementation of GEMVER,
 * and then apply Exo scheduling primitives to:
 *   - tile the 2D loops over A for better cache locality,
 *   - expose coarse-grain parallelism with parallelize_loop,
 *   - keep the scalar/vector interface identical to the original C driver.
 *
 * TI and TJ are compile-time tunable tile sizes for the i- and j-dimensions.
 */

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM
from exo.frontend.syntax import *

# Compile-time tunable tile sizes for the i- and j-dimensions.  These are the
# main knobs for cache-aware tuning of the kernel.
TI = 32
TJ = 32


@proc
def kernel_gemver_base(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    u1: DATA_TYPE[n] @ DRAM,
    v1: DATA_TYPE[n] @ DRAM,
    u2: DATA_TYPE[n] @ DRAM,
    v2: DATA_TYPE[n] @ DRAM,
    w: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    z: DATA_TYPE[n] @ DRAM,
):
    # Phase 1: rank-1 updates
    #   A := A + u1 * v1^T + u2 * v2^T
    for i in seq(0, n):
        for j in seq(0, n):
            A[i, j] += u1[i] * v1[j] + u2[i] * v2[j]

    # Phase 2: x := x + beta * A^T * y
    # Note: we use an explicit reduction form (+=) so Exo can reason about
    #       dependences along j.
    for i in seq(0, n):
        for j in seq(0, n):
            x[i] += beta * A[j, i] * y[j]

    # Phase 3: x := x + z
    for i in seq(0, n):
        x[i] += z[i]

    # Phase 4: w := w + alpha * A * x
    for i in seq(0, n):
        for j in seq(0, n):
            w[i] += alpha * A[i, j] * x[j]


# ------------------------
# Scheduling / optimization
# ------------------------

kernel_gemver_opt = kernel_gemver_base

# 1) Tile and parallelize the rank-1 updates on A.
#    - Tile both i and j to operate on TI x TJ tiles of A.
#    - Parallelize the outermost i-tile loop.
#    This improves spatial locality on A and the vectors u1/u2/v1/v2, and
#    exposes outer-loop parallelism across tiles of rows.
kernel_gemver_opt = divide_loop(kernel_gemver_opt, "i #0", TI, ["io", "ii"])
kernel_gemver_opt = divide_loop(kernel_gemver_opt, "j #0", TJ, ["jo", "ji"])
# Reorder the inner two loops so that we iterate tiles in (io, jo, ii, ji)
# order, i.e., tile-by-tile in A.
kernel_gemver_opt = reorder_loops(kernel_gemver_opt, "ii jo")
# Parallelize across i-tiles.
kernel_gemver_opt = parallelize_loop(kernel_gemver_opt, "io")


# 2) Parallelize the x update (matrix-vector with A^T) across blocks of i.
#    Accesses to A[j, i] are column-wise and thus inherently strided in A.
#    We preserve the original access pattern but:
#      - strip-mine i with factor TI,
#      - parallelize the outer strip loop, which is safe because each i-strip
#        works on a disjoint slice of x.
kernel_gemver_opt = divide_loop(kernel_gemver_opt, "i #0", TI, ["i2o", "i2i"])
kernel_gemver_opt = parallelize_loop(kernel_gemver_opt, "i2o")


# 3) Tile and parallelize the w update (matrix-vector with A).
#    Here A is accessed row-major (A[i, j]), so we again:
#      - tile i and j (TI x TJ),
#      - parallelize over i-tiles (each tile updates a disjoint slice of w).
kernel_gemver_opt = divide_loop(kernel_gemver_opt, "i #1", TI, ["iw_o", "iw_i"])
kernel_gemver_opt = divide_loop(kernel_gemver_opt, "j #1", TJ, ["jw_o", "jw_i"])
kernel_gemver_opt = parallelize_loop(kernel_gemver_opt, "iw_o")


# Simplify the resulting code (fold trivial expressions/guards, etc.).
kernel_gemver_opt = simplify(kernel_gemver_opt)

# Expose the optimized kernel under the name expected by the C driver.
kernel_gemver = rename(kernel_gemver_opt, "kernel_gemver")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(u1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(u2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(w,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(z,  DATA_TYPE, N, n);

